/// Returns true if `n` is a power of two (and positive).
/// (Included because it was listed in the problem statement.)
pub fn is_2_pow(n: i32) -> bool {
    n > 0 && (n & (n - 1)) == 0
}

/// Lower-bound search for `x` in the sorted range `a[lo..hi]`.
/// Returns `k` in `[lo, hi]` such that:
/// - for all r in [lo, k): a[r] < x
/// - for all r in [k, hi): a[r] >= x
pub fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    assert!(lo <= hi);
    assert!(hi <= a.len());

    let mut l = lo;
    let mut r = hi; // exclusive

    while l < r {
        let m = l + (r - l) / 2;
        if a[m] < x {
            l = m + 1;
        } else {
            r = m;
        }
    }

    l
}

/// Computes the lower-bound insertion position of `x` within the first 1000 elements of `a`.
/// Assumes `a.len() >= 1000` and `a[0..1000]` is sorted in nondecreasing order.
pub fn search_1000(a: &[i32], x: i32) -> usize {
    assert!(a.len() >= 1000);
    search_range_helper(a, x, 0, 1000)
}